"use client";

import React, { useState, useMemo } from "react";
import {
    FileText,
    UploadCloud,
    MoreVertical,
    Download,
    Trash2,
    Eye,
    Search,
    Filter,
    Clock,
    CheckCircle2,
    AlertCircle,
    Plus
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";
import PageBreadcrumb from "@/components/common/PageBreadCrumb";

/* ========================
   REFINED TYPES
======================== */
type DocStatus = "Verified" | "Pending" | "Rejected" | "Expiring Soon";

interface DocumentItem {
    id: string;
    name: string;
    category: "Identity" | "Education" | "Company" | "Tax";
    size: string;
    uploadDate: string;
    status: DocStatus;
    expiryDate?: string;
}

const initialDocs: DocumentItem[] = [
    { id: "1", name: "Aadhar_Card.pdf", category: "Identity", size: "1.2 MB", uploadDate: "12 Jan 2026", status: "Verified" },
    { id: "2", name: "Degree_Certificate.pdf", category: "Education", size: "2.4 MB", uploadDate: "10 Jan 2026", status: "Verified" },
    { id: "3", name: "Passport_Copy.pdf", category: "Identity", size: "3.1 MB", uploadDate: "05 Jan 2026", status: "Expiring Soon", expiryDate: "20 Mar 2026" },
    { id: "4", name: "Offer_Letter.pdf", category: "Company", size: "850 KB", uploadDate: "01 Jan 2026", status: "Verified" },
    { id: "5", name: "Investment_Proof.zip", category: "Tax", size: "5.5 MB", uploadDate: "13 Jan 2026", status: "Pending" },
];

export default function EmployeeDocumentHub() {
    const [docs, setDocs] = useState<DocumentItem[]>(initialDocs);
    const [search, setSearch] = useState("");
    const [activeTab, setActiveTab] = useState<string>("All");
    const [showUploadModal, setShowUploadModal] = useState(false);

    const filteredDocs = useMemo(() => {
        return docs.filter(doc => {
            const matchesSearch = doc.name.toLowerCase().includes(search.toLowerCase());
            const matchesTab = activeTab === "All" || doc.category === activeTab;
            return matchesSearch && matchesTab;
        });
    }, [search, activeTab, docs]);

    const handleDelete = (id: string) => {
        if(confirm("Are you sure you want to delete this document?")) {
            setDocs(docs.filter(d => d.id !== id));
        }
    };

    return (
        <div className="p-6 space-y-6 bg-[#F8F9FB] dark:bg-[#0B1120] min-h-screen">
            <PageBreadcrumb pageTitle="Document Hub" />

            {/* 1. KPI SECTION */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <DocStatCard icon={<FileText />} label="Total Files" value={docs.length.toString()} color="brand" />
                <DocStatCard icon={<CheckCircle2 />} label="Verified" value="3" color="emerald" />
                <DocStatCard icon={<Clock />} label="Pending" value="1" color="amber" />
                <DocStatCard icon={<AlertCircle />} label="Action Required" value="1" color="red" />
            </div>

            {/* 2. ACTIONS BAR */}
            <div className="bg-white dark:bg-gray-900 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-800 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
                    {["All", "Identity", "Education", "Company", "Tax"].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                                activeTab === tab 
                                ? "bg-brand-500 text-white shadow-md shadow-brand-500/20" 
                                : "text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800"
                            }`}
                        >
                            {tab}
                        </button>
                    ))}
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
                        <input
                            placeholder="Find a document..."
                            className="pl-9 w-full border-none bg-gray-50 dark:bg-gray-800 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-brand-500 transition-all"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                    <button 
                        onClick={() => setShowUploadModal(true)}
                        className="bg-brand-500 hover:bg-brand-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 text-sm font-bold shadow-lg shadow-brand-500/20 transition-all"
                    >
                        <Plus size={18} /> Upload
                    </button>
                </div>
            </div>

            {/* 3. DOCUMENTS TABLE */}
            <div className="bg-white dark:bg-gray-900 rounded-[2rem] shadow-sm border border-gray-100 dark:border-gray-800 overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[11px] uppercase tracking-widest text-gray-400">
                            <th className="px-6 py-4 font-black">Document Name</th>
                            <th className="px-6 py-4 font-black">Category</th>
                            <th className="px-6 py-4 font-black">Size</th>
                            <th className="px-6 py-4 font-black">Status</th>
                            <th className="px-6 py-4 font-black">Uploaded</th>
                            <th className="px-6 py-4 font-black text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                        {filteredDocs.map((doc) => (
                            <tr key={doc.id} className="group hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 bg-brand-50 dark:bg-brand-500/10 rounded-xl flex items-center justify-center text-brand-600">
                                            <FileText size={20} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-bold text-gray-900 dark:text-white">{doc.name}</p>
                                            {doc.expiryDate && (
                                                <p className="text-[10px] text-red-500 font-bold">Expires: {doc.expiryDate}</p>
                                            )}
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className="text-xs font-medium text-gray-500">{doc.category}</span>
                                </td>
                                <td className="px-6 py-4">
                                    <span className="text-xs text-gray-400 font-mono">{doc.size}</span>
                                </td>
                                <td className="px-6 py-4">
                                    <StatusBadge status={doc.status} />
                                </td>
                                <td className="px-6 py-4 text-xs text-gray-500">
                                    {doc.uploadDate}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex justify-end gap-2">
                                        <button className="p-2 text-gray-400 hover:text-brand-600 transition-colors"><Eye size={18}/></button>
                                        <button className="p-2 text-gray-400 hover:text-brand-600 transition-colors"><Download size={18}/></button>
                                        <button 
                                            onClick={() => handleDelete(doc.id)}
                                            className="p-2 text-gray-400 hover:text-red-500 transition-colors"
                                        >
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

/* --- HELPER COMPONENTS --- */

const DocStatCard = ({ icon, label, value, color }: any) => (
    <div className="bg-white dark:bg-gray-900 p-6 rounded-[2rem] border border-gray-100 dark:border-gray-800 shadow-sm">
        <div className={`w-12 h-12 rounded-2xl bg-${color}-50 dark:bg-${color}-500/10 flex items-center justify-center text-${color}-600 mb-4`}>
            {icon}
        </div>
        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{label}</p>
        <h3 className="text-2xl font-black text-gray-900 dark:text-white mt-1">{value}</h3>
    </div>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
    const variants = {
        Verified: { color: "success" },
        Pending: { color: "warning" },
        Rejected: { color: "error" },
        "Expiring Soon": { color: "warning" },
    };
    return <Badge size="sm" color={variants[status].color as any}>{status}</Badge>;
};